    hub=json.load(open(f'data/hubs/{section}.json',encoding='utf-8'))
    root=next((r for r in T.get('roots',[]) if r.get('key')==section), None)
    if root is None:
        reports.append({'section':section,'ok':False,'error':'missing root in taxonomy.json'}); continue
    admin_tree=root.get('children',[])
    if section=='thu-vien':
        # Public user tree is grouped by kind tabs. Admin root first level must include the same visible kind tree.
        public_kinds=hub.get('libraryKinds',[])
        admin_kinds=admin_tree
        def simp_kind(x):
            return {'key':x.get('key',''), 'label':x.get('label',''), 'count':x.get('count',0), 'children':simp_children(x.get('children',[]))}
        def simp_children(items):
            return [{'key':i.get('key',''), 'label':i.get('label',''), 'count':i.get('count',0), 'children':simp_children(i.get('children',[]))} for i in items]
        a=[simp_kind(x) for x in admin_kinds]
        b=[simp_kind(x) for x in public_kinds]
    else:
