            return [{'key':i.get('key',''), 'label':i.get('label',''), 'count':i.get('count',0), 'children':simp_children(i.get('children',[]))} for i in items]
        a=simp_children(admin_tree)
        b=simp_children(hub.get('taxonomy',[]))
    reports.append({'section':section,'ok':a==b,'admin_top':len(a),'public_top':len(b),'first_diff':None if a==b else {'admin':a[:3],'public':b[:3]}})
