import json
from collections import defaultdict
T=json.load(open('data/taxonomy.json',encoding='utf-8'))

def simp_children(items):
    return [{'key':i.get('key',''), 'label':i.get('label',''), 'count':i.get('count',0), 'children':simp_children(i.get('children',[]))} for i in items]

def build_taxonomy_from_articles(articles):
    lv1={}
    for a in articles:
        k1=a.get('topic_lv1_key') or ''
        l1=a.get('topic_lv1_label') or k1
        k2=a.get('topic_lv2_key') or ''
        l2=a.get('topic_lv2_label') or k2
        if not k1: continue
        node=lv1.setdefault(k1, {'key':k1,'label':l1,'count':0,'children_map':{}})
        node['count']+=1
        if k2:
            child=node['children_map'].setdefault(k2, {'key':k2,'label':l2,'count':0,'children':[]})
            child['count']+=1
    out=[]
    for n in lv1.values():
        children=sorted(n['children_map'].values(), key=lambda x:(-x['count'], x['label']))
        out.append({'key':n['key'],'label':n['label'],'count':n['count'],'children':children})
    return sorted(out, key=lambda x:(-x['count'], x['label']))

reports=[]
for section in ['thu-vien','ban-tin']:
    hub=json.load(open(f'data/hubs/{section}.json',encoding='utf-8'))
    root=next((r for r in T.get('roots',[]) if r.get('key')==section), None)
    admin=simp_children(root.get('children',[]))
    if section=='thu-vien':
        public=[]
        for kind in hub.get('libraryKinds',[]):
            subset=[a for a in hub.get('articles',[]) if a.get('library_kind_key')==kind.get('key')]
            public.append({'key':kind.get('key',''),'label':kind.get('label',''),'count':kind.get('count',0),'children':build_taxonomy_from_articles(subset)})
    else:
        public=simp_children(hub.get('taxonomy',[]))
    reports.append({'section':section,'ok':admin==public,'admin_top':len(admin),'public_top':len(public),'first_diff':None if admin==public else {'admin':admin[:1], 'public':public[:1]}})
print(json.dumps({'ok':all(r['ok'] for r in reports), 'reports':reports},ensure_ascii=False,indent=2))
if not all(r['ok'] for r in reports): raise SystemExit(2)
