import json
T=json.load(open('data/taxonomy.json',encoding='utf-8'))
def prune(items, depth):
    out=[]
    for i in items:
        node={'key':i.get('key',''), 'label':i.get('label',''), 'count':i.get('count',0), 'children':[]}
        if depth>1:
            node['children']=prune(i.get('children',[]), depth-1)
        out.append(node)
    return out

def build_taxonomy_from_articles(articles):
    m={}
    for a in articles:
        k1=a.get('topic_lv1_key') or ''; l1=a.get('topic_lv1_label') or k1
        k2=a.get('topic_lv2_key') or ''; l2=a.get('topic_lv2_label') or k2
        if not k1: continue
        n=m.setdefault(k1, {'key':k1,'label':l1,'count':0,'_children':{}})
        n['count']+=1
        if k2:
            c=n['_children'].setdefault(k2, {'key':k2,'label':l2,'count':0,'children':[]})
            c['count']+=1
    out=[]
    for n in m.values():
        out.append({'key':n['key'],'label':n['label'],'count':n['count'],'children':sorted(n['_children'].values(), key=lambda x:(-x['count'],x['label']))})
    return sorted(out,key=lambda x:(-x['count'],x['label']))
reports=[]
for section in ['thu-vien','ban-tin']:
    h=json.load(open(f'data/hubs/{section}.json',encoding='utf-8'))
    root=next(r for r in T['roots'] if r['key']==section)
    if section=='thu-vien':
        admin=prune(root.get('children',[]),3)
        public=[]
        for kind in h['libraryKinds']:
            subset=[a for a in h['articles'] if a.get('library_kind_key')==kind['key']]
            public.append({'key':kind['key'],'label':kind['label'],'count':kind['count'],'children':build_taxonomy_from_articles(subset)})
    else:
        admin=prune(root.get('children',[]),2)
        public=prune(h.get('taxonomy',[]),2)
    reports.append({'section':section,'ok':admin==public,'admin_top':len(admin),'public_top':len(public),'visible_depth':3 if section=='thu-vien' else 2,'first_diff':None if admin==public else {'admin':admin[:1],'public':public[:1]}})
print(json.dumps({'ok':all(r['ok'] for r in reports), 'reports':reports},ensure_ascii=False,indent=2))
if not all(r['ok'] for r in reports): raise SystemExit(2)
